CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS entries (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, title TEXT NOT NULL, slug TEXT NOT NULL, excerpt TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', body_format TEXT NOT NULL DEFAULT 'text', profile_details TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '', author TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft', published_at TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, meta_title TEXT NOT NULL DEFAULT '', meta_description TEXT NOT NULL DEFAULT '', og_title TEXT NOT NULL DEFAULT '', og_description TEXT NOT NULL DEFAULT '', og_image TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL, UNIQUE(type, slug));
CREATE INDEX IF NOT EXISTS entries_listing ON entries(type, status, sort_order);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', subject TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL, notice_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, bucket TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_bucket ON attempts(bucket, created_at);
CREATE TABLE IF NOT EXISTS revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, entry_id INTEGER NOT NULL, snapshot TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media (id INTEGER PRIMARY KEY AUTOINCREMENT, path TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, data TEXT NOT NULL DEFAULT '', expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS media_files (path TEXT PRIMARY KEY, content_type TEXT NOT NULL, data TEXT NOT NULL, size INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS content_backups (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS url_redirects (id INTEGER PRIMARY KEY AUTOINCREMENT, source_path TEXT NOT NULL UNIQUE, target_path TEXT NOT NULL, status_code INTEGER NOT NULL DEFAULT 301, enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS seo_urls (path TEXT PRIMARY KEY, sitemap_enabled INTEGER NOT NULL DEFAULT 1, noindex INTEGER NOT NULL DEFAULT 0, lastmod TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
